local Component=require(script.Parent.Parent.Base.Component)
return function(ctx,items,callback) local f=Instance.new("Frame",ctx.Parent);f.Name="Breadcrumbs";f.Size=UDim2.new(1,0,0,32);f.BackgroundTransparency=1;local x=0;for i,item in ipairs(items or {})do local b=Instance.new("TextButton",f);b.Position=UDim2.fromOffset(x,0);b.Size=UDim2.fromOffset(math.max(50,#tostring(item)*7+18),30);b.BackgroundTransparency=1;b.Text=tostring(item);b.TextColor3=ctx.Theme:Get(i==#items and "Text" or "Muted");b.Font=Enum.Font.Gotham;b.TextSize=12;ctx.Input:BindPress(b,function()if callback then callback(item,i)end end);x+=b.Size.X.Offset;if i<#items then local sep=Instance.new("TextLabel",f);sep.Position=UDim2.fromOffset(x,0);sep.Size=UDim2.fromOffset(18,30);sep.BackgroundTransparency=1;sep.Text="/";sep.TextColor3=ctx.Theme:Get("Muted");sep.Font=Enum.Font.Gotham;sep.TextSize=12;x+=18 end end;return Component.new(f,ctx) end
